+export async function listTools() {
+  return [
+    {
+      name: 'users_get_many',
+      description: 'Look up multiple users by id in a single batch. Returns one line per requested id in request order, marking missing users without failing the batch.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          user_ids: {
+            type: 'array',
+            items: { type: 'string' },
+            minItems: 1,
+            maxItems: 5
+          }
+        },
+        required: ['user_ids'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'users_get_many') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+
+  // Reject extra fields (additionalProperties: false)
+  const keys = Object.keys(args);
+  for (const k of keys) {
+    if (k !== 'user_ids') {
+      throw new Error(`Unexpected field: ${k}`);
+    }
+  }
+
+  if (!('user_ids' in args)) {
+    throw new Error('user_ids is required');
+  }
+
+  const { user_ids } = args;
+
+  // Must be a valid array
+  if (!Array.isArray(user_ids)) {
+    throw new Error('user_ids must be an array');
+  }
+
+  // Non-empty
+  if (user_ids.length === 0) {
+    throw new Error('user_ids must not be empty');
+  }
+
+  // At most 5 entries
+  if (user_ids.length > 5) {
+    throw new Error('user_ids must have at most 5 entries');
+  }
+
+  // Each entry must be a string
+  for (const id of user_ids) {
+    if (typeof id !== 'string') {
+      throw new Error('user_ids must contain only strings');
+    }
+  }
+
+  // Reject duplicate ids
+  const seen = new Set();
+  for (const id of user_ids) {
+    if (seen.has(id)) {
+      throw new Error(`Duplicate user_id: ${id}`);
+    }
+    seen.add(id);
+  }
+
+  // One line per requested id in request order, marking missing users
+  const lines = user_ids.map(id => {
+    const user = users[id];
+    return user ? `${id}: ${user.name}` : `${id}: not found`;
+  });
+
+  return {
+    content: [{ type: 'text', text: lines.join('\n') }]
+  };
